# EXT D P
for i in 1 2 3; do curl -s http://127.0.0.1:${PORT}/__reset >/dev/null; node run-task.mjs "$(jq -nc --arg ext $EXT --arg d $D --arg t "$P$i" --arg u "http://127.0.0.1:${PORT}/" '{ext:$ext,display:$d,tag:$t,url:$u,prompt:"新建验收：备注写随手记并回车，正文写好，点刷新，分类选项目，再新建一条笔记，标题写周会纪要，保存。",maxSec:200,after:[{shot:"receipt",wait:1000,text:".plan-card .plan-receipt-line"},{check:"JSON.stringify([memo.value, document.getElementById(\"editor\").textContent, kind.value])",shot:"before-undo",wait:200},{click:".plan-card .plan-undo",shot:"undo",wait:3500,text:".plan-card .plan-receipt-line"},{check:"JSON.stringify([memo.value, document.getElementById(\"editor\").textContent, kind.value])",shot:"after-undo",wait:200}]}')" 2>&1 | tail -1 | cut -c1-100; echo "SAVES $i $(curl -s http://127.0.0.1:${PORT}/__saves)"; done
